#
# ══════════════════════════════════════════════════════════════════════
#  OVNode — OpenVPN Node Agent Installer
#
#  Install :  bash <(curl -Ls https://anonysec.github.io/OVNode/install.sh)
#  Update  :  bash <(curl -Ls URL) update
#  Remove  :  bash <(curl -Ls URL) uninstall
#
#  Installs the agent (uv + systemd/Docker), scaffolds the OpenVPN server
#  (PKI is generated by the agent on first boot), enables NAT/masquerade so
#  client traffic can route through the node, and verifies /sync/health.
# ══════════════════════════════════════════════════════════════════════

set -Eeuo pipefail

# ── Config ─────────────────────────────────────────────────────────────
REPO="anonysec/OVNode"
BRANCH="main"
APP_DIR="/opt/ovnode"
DATA_BASE="/var/lib/ovnode"
OPENVPN_ROOT="/etc/openvpn"
DEFAULT_PORT=2083
DEFAULT_VPN=1194
SYSTEMD_SERVICE="ovnode.service"
NAT_SERVICE="ovnode-nat.service"
VERSION="2.2"

# ── Colors ─────────────────────────────────────────────────────────────
NC=$'\033[0m'; B=$'\033[1m'; D=$'\033[2m'
WH=$'\033[97m'; GR=$'\033[32m'; RD=$'\033[31m'
YL=$'\033[33m'; CY=$'\033[36m'; GY=$'\033[90m'
[[ -t 1 ]] || { NC=''; B=''; D=''; WH=''; GR=''; RD=''; YL=''; BL=''; CY=''; GY=''; }

# ── UI helpers ─────────────────────────────────────────────────────────
line()  { echo -e "  $1" >&2; }
step()  { line "${GR}  ✓${NC} $1"; }
info()  { line "${CY}  →${NC} $1"; }
warn()  { line "${YL}  ⚠${NC} $1"; }
field() { printf "  ${GY}%-18s${NC} %s\n" "$1" "$2"; }
sep()   { line "${GY}$(printf '%.0s─' {1..56})${NC}"; }

spinner() {
    local msg="$1" pid=$2 chars='⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏' i=0 rc=0
    while kill -0 "$pid" 2>/dev/null; do
        printf "\r  ${CY}%s${NC} %-46s" "${chars:$((i%9)):1}" "$msg" >&2
        sleep 0.1; i=$(( i + 1 ))
    done
    wait "$pid" 2>/dev/null || rc=$?
    printf "\r\033[K" >&2
    [[ $rc -eq 0 ]] && step "$msg" || { line "${RD}  ✗${NC} $msg"; return 1; }
}

die()  { echo -e "\n  ${RD}Error:${NC} $1\n" >&2; exit 1; }
trap 'echo -e "\n  ${RD}Interrupted.${NC}" >&2; exit 1' INT TERM

is_tty() { [[ -t 0 ]]; }
ask() {
    local label="$1" default="$2" hidden="${3:-}" val=""
    if is_tty; then
        if [[ "$hidden" == "h" ]]; then
            printf "  ${WH}%-18s${NC} ${GY}[%s]${NC} : " "$label" "$default"
            read -rs val; printf "\n"
        else
            printf "  ${WH}%-18s${NC} ${GY}[%s]${NC} : " "$label" "$default"
            read -r val
        fi
    fi
    if [[ -z "$val" ]]; then val="$default"; fi
    echo "$val"
}

confirm() {
    [[ "$YES" -eq 1 ]] && return 0
    if is_tty; then
        printf "  %s [${GR}Y${NC}/n] : " "$1"
        read -r c
        [[ ! "$c" =~ ^[Nn]$ ]]
    else
        return 0
    fi
}

# ── OS / package manager ───────────────────────────────────────────────
OS_ID="" OS_NAME="" PKG_INSTALL="" PKG_UPDATE=""

detect_os() {
    if [[ -f /etc/os-release ]]; then
        # shellcheck disable=SC1091
        . /etc/os-release
        OS_ID="${ID:-}"; OS_NAME="${PRETTY_NAME:-$OS_ID}"
    else
        die "Unsupported OS — no /etc/os-release found."
    fi
    case "$OS_ID" in
        debian|ubuntu)      PKG_UPDATE="apt-get update -qq";  PKG_INSTALL="apt-get install -y -qq" ;;
        rhel|centos|rocky|almalinux|fedora)
            if command -v dnf >/dev/null 2>&1; then
                PKG_UPDATE="dnf -q makecache"; PKG_INSTALL="dnf install -y -q"
            else
                PKG_UPDATE="yum -q makecache"; PKG_INSTALL="yum install -y -q"
            fi ;;
        arch)               PKG_UPDATE="pacman -Sy --noconfirm"; PKG_INSTALL="pacman -S --noconfirm" ;;
        alpine)             PKG_UPDATE="apk update -q";         PKG_INSTALL="apk add -q" ;;
        *) die "Unsupported distribution: ${OS_ID:-unknown}" ;;
    esac
}

pkg_install() {
    info "Installing: $*"
    $PKG_UPDATE >/dev/null 2>&1 || true
    $PKG_INSTALL "$@" >/dev/null 2>&1 || die "Failed to install: $*"
}

has_systemd() { command -v systemctl >/dev/null 2>&1 && [[ -d /run/systemd/system ]]; }

# ── Args ───────────────────────────────────────────────────────────────
PORT="" API_KEY="" VPN_PORT="" NODE_NAME=""
TLS_METHOD="none" TLS_DOMAIN="" TLS_KEY="" TLS_CERT=""
DOCKER=0 ACTION="install" YES=0 PURGE=0 NO_NAT=0 IPV6=0

show_help() {
    cat << 'EOF'
  Usage:
    bash <(curl -Ls https://anonysec.github.io/OVNode/install.sh)
    bash <(curl -Ls URL) update
    bash <(curl -Ls URL) uninstall

  Commands:
    (none)              Install or update OVNode
    update              Pull latest changes and restart (with backup)
    uninstall           Remove OVNode (data kept unless --purge)

  Flags:
    --port PORT         Service port (default: 2083)
    --api-key KEY       API key (min 16 chars; auto-generated if empty)
    --vpn-port PORT     OpenVPN port (default: 1194)
    --name NAME         Node name (default: node-1)
    --tls METHOD        letsencrypt | letsencrypt-ip | selfsigned | custom | none
    --tls-domain DOM    Domain or IP for Let's Encrypt
    --tls-key K         Key file (with --tls custom)
    --tls-cert C        Cert file (with --tls custom)
    --docker            Run inside Docker (host networking, built from source)
    --ipv6              Enable IPv6 (ULA pool + route push) on the VPN
    --no-nat            Skip IP forwarding + NAT masquerade setup
    --yes  | -y         Non-interactive: accept defaults, skip confirmations
    --purge             With uninstall: also remove data and OpenVPN config
    --help | -h         Show this help
EOF
    exit 0
}

parse_args() {
    while [[ $# -gt 0 ]]; do
        case "$1" in
            --port)       [[ $# -ge 2 ]] || die "--port needs a value"; PORT="$2"; shift 2 ;;
            --api-key)    [[ $# -ge 2 ]] || die "--api-key needs a value"; API_KEY="$2"; shift 2 ;;
            --vpn-port)   [[ $# -ge 2 ]] || die "--vpn-port needs a value"; VPN_PORT="$2"; shift 2 ;;
            --name)       [[ $# -ge 2 ]] || die "--name needs a value"; NODE_NAME="$2"; shift 2 ;;
            --tls)        [[ $# -ge 2 ]] || die "--tls needs a value"; TLS_METHOD="$2"; shift 2 ;;
            --tls-domain) [[ $# -ge 2 ]] || die "--tls-domain needs a value"; TLS_DOMAIN="$2"; shift 2 ;;
            --tls-key)    [[ $# -ge 2 ]] || die "--tls-key needs a value"; TLS_KEY="$2"; shift 2 ;;
            --tls-cert)   [[ $# -ge 2 ]] || die "--tls-cert needs a value"; TLS_CERT="$2"; shift 2 ;;
            --ipv6)       IPV6=1; shift ;;
            --docker)     DOCKER=1; shift ;;
            --no-nat)     NO_NAT=1; shift ;;
            --yes|-y)     YES=1; shift ;;
            --purge)      PURGE=1; shift ;;
            --uninstall)  ACTION="uninstall"; shift ;;
            --help|-h)    show_help ;;
            update)       ACTION="update"; shift ;;
            uninstall)    ACTION="uninstall"; shift ;;
            *)            die "Unknown option: $1 (--help for usage)" ;;
        esac
    done
}

# ── Validation ─────────────────────────────────────────────────────────
is_port() { [[ "$1" =~ ^[0-9]+$ ]] && (( $1 >= 1 && $1 <= 65535 )); }

validate_input() {
    is_port "$PORT"   || die "Invalid service port: '$PORT'"
    is_port "$VPN_PORT" || die "Invalid OpenVPN port: '$VPN_PORT'"
    [[ -n "$NODE_NAME" ]] || NODE_NAME="node-1"
    [[ "$NODE_NAME" =~ ^[A-Za-z0-9_-]{1,64}$ ]] || die "Invalid node name"
    [[ -n "$API_KEY" ]] || die "API key is required (--api-key, or interactive install auto-generates one)"
    [[ ${#API_KEY} -ge 16 ]] || die "API key must be at least 16 characters (openssl rand -hex 32)"
    case "$TLS_METHOD" in
        letsencrypt|letsencrypt-ip|selfsigned|custom|none) ;;
        *) die "Invalid TLS method: '$TLS_METHOD'" ;;
    esac
    if [[ "$TLS_METHOD" == "letsencrypt" || "$TLS_METHOD" == "letsencrypt-ip" ]]; then
        [[ -n "$TLS_DOMAIN" ]] || die "--tls-domain is required for Let's Encrypt"
    fi
    if [[ "$TLS_METHOD" == "custom" ]]; then
        [[ -f "$TLS_KEY" && -f "$TLS_CERT" ]] || die "Custom TLS key/cert files not found"
    fi
}

port_in_use() { ss -ltn 2>/dev/null | awk -v p=":${1}$" '$4 ~ p {exit 0} END {exit 1}'; }

find_free_port() {
    local port="${1:-$DEFAULT_PORT}"
    while port_in_use "$port"; do ((port++)); done
    echo "$port"
}

# ── Toolchain ──────────────────────────────────────────────────────────
ensure_uv() {
    if command -v uv >/dev/null 2>&1; then
        UV_BIN="$(command -v uv)"; step "uv found: $UV_BIN"; return
    fi
    info "Installing uv (Python package manager)..."
    curl -LsSf https://astral.sh/uv/install.sh | sh >/dev/null 2>&1 || \
        python3 -m pip install --quiet uv >/dev/null 2>&1 || \
        die "Could not install uv."
    UV_BIN="$(command -v uv 2>/dev/null || true)"
    [[ -n "$UV_BIN" ]] || UV_BIN="$HOME/.local/bin/uv"
    [[ -x "$UV_BIN" ]] || die "uv not found after install"
    step "uv installed: $UV_BIN"
}

# ── Backups ────────────────────────────────────────────────────────────
backup_dir() {
    local src="$1" label="$2"
    [[ -d "$src" ]] || return 0
    mkdir -p /var/backups
    local stamp; stamp="$(date +%Y%m%d-%H%M%S)"
    local base; base="$(basename "$src")"
    local file="/var/backups/${label}-${base}-${stamp}.tar.gz"
    info "Backing up ${label} data to $file ..."
    tar -czf "$file" -C "$(dirname "$src")" "$base" 2>/dev/null \
        || warn "Backup failed for $src — continuing anyway"
    step "Backup saved: $file"
}

# ── TLS ────────────────────────────────────────────────────────────────
generate_selfsigned() {
    info "Generating self-signed certificate..."
    mkdir -p /etc/ssl/self-signed
    local cn; cn="$(hostname -I 2>/dev/null | awk '{print $1}')"
    openssl req -x509 -nodes -days 3650 -newkey rsa:2048 \
        -keyout /etc/ssl/self-signed/privkey.pem \
        -out /etc/ssl/self-signed/fullchain.pem \
        -subj "/C=US/ST=Local/L=Local/O=OVNode/CN=${cn}" >/dev/null 2>&1
    step "Self-signed certificate generated"
}

ensure_acme() {
    if [[ ! -x "$HOME/.acme.sh/acme.sh" ]]; then
        info "Installing acme.sh..."
        curl -s https://get.acme.sh | sh >/dev/null 2>&1 || die "Failed to install acme.sh"
    fi
}

issue_letsencrypt() {
    local domain="$1" is_ip="$2"
    ensure_acme
    local email="acme-$(openssl rand -hex 4)@example.com"
    local outdir="/etc/letsencrypt/$domain"
    mkdir -p "$outdir"

    if [[ -f "$outdir/fullchain.pem" ]]; then
        local expiry days_left=0
        expiry="$(openssl x509 -enddate -noout -in "$outdir/fullchain.pem" 2>/dev/null | cut -d= -f2)"
        days_left=$(( ($(date -d "$expiry" +%s 2>/dev/null || echo 0) - $(date +%s)) / 86400 ))
        if (( days_left > 7 )); then
            step "Existing certificate valid for ${days_left} more days"
            return 0
        fi
        warn "Certificate expires soon (${days_left}d) — renewing..."
    fi

    local extra_args=()
    if [[ "$is_ip" == "1" ]]; then extra_args=(--certificate-profile shortlived --days 6); fi

    "$HOME/.acme.sh/acme.sh" --issue -d "$domain" --standalone "${extra_args[@]}" \
        --accountemail "$email" >/dev/null 2>&1 \
        || die "Failed to issue Let's Encrypt certificate for $domain"

    "$HOME/.acme.sh/acme.sh" --install-cert -d "$domain" \
        --key-file "$outdir/privkey.pem" \
        --fullchain-file "$outdir/fullchain.pem" \
        --reloadcmd "systemctl restart $SYSTEMD_SERVICE >/dev/null 2>&1 || true" >/dev/null 2>&1 \
        || die "Failed to install certificate to $outdir"
    step "Certificate installed to $outdir"
}

setup_tls() {
    case "$TLS_METHOD" in
        none) ;;
        selfsigned) generate_selfsigned ;;
        letsencrypt)    issue_letsencrypt "$TLS_DOMAIN" "0" ;;
        letsencrypt-ip) issue_letsencrypt "$TLS_DOMAIN" "1" ;;
        custom)
            local out="/etc/letsencrypt/${TLS_DOMAIN:-node}"
            mkdir -p "$out"
            cp "$TLS_KEY" "$out/privkey.pem"
            cp "$TLS_CERT" "$out/fullchain.pem"
            TLS_KEY="$out/privkey.pem"; TLS_CERT="$out/fullchain.pem"
            ;;
    esac
}

# ── NAT / routing ──────────────────────────────────────────────────────
write_nat_files() {
    # Persistent IP forwarding
    cat > /etc/sysctl.d/99-ovnode.conf << 'SYSCTL'
# OVNode: allow OpenVPN clients to route through this host
net.ipv4.ip_forward = 1
SYSCTL
    sysctl -p /etc/sysctl.d/99-ovnode.conf >/dev/null 2>&1 || true

    # NAT helper script (masquerade tun traffic out the default interface)
    cat > /usr/local/sbin/ovnode-nat.sh << 'NAT'
#!/bin/bash
# OVNode NAT: masquerade VPN client traffic through the default uplink.
IFACE="$(ip route show default 2>/dev/null | awk '{print $5; exit}')"
if [[ -z "$IFACE" ]]; then echo "ovnode-nat: no default interface found" >&2; exit 1; fi
if ! iptables -t nat -C POSTROUTING -o "$IFACE" -j MASQUERADE 2>/dev/null; then
    iptables -t nat -A POSTROUTING -o "$IFACE" -j MASQUERADE
fi
NAT
    chmod +x /usr/local/sbin/ovnode-nat.sh

    cat > "/etc/systemd/system/$NAT_SERVICE" << UNIT
[Unit]
Description=OVNode NAT (masquerade VPN traffic)
After=network-online.target
Wants=network-online.target

[Service]
Type=oneshot
RemainAfterExit=yes
ExecStart=/usr/local/sbin/ovnode-nat.sh

[Install]
WantedBy=multi-user.target
UNIT
    systemctl daemon-reload >/dev/null 2>&1
    systemctl enable "$NAT_SERVICE" >/dev/null 2>&1
    systemctl start "$NAT_SERVICE" >/dev/null 2>&1 && step "NAT + IP forwarding enabled" \
        || warn "Could not start NAT service — VPN clients may not route traffic"
}

setup_nat() {
    if [[ "$NO_NAT" -eq 1 ]]; then info "Skipping NAT setup (--no-nat)"; return; fi
    if ! command -v iptables >/dev/null 2>&1; then
        info "Installing iptables/iproute2 for NAT..."
        pkg_install iptables iproute2
    fi
    # Some distros ship iptables-nft without a persistent service; our
    # oneshot unit handles persistence on every boot.
    write_nat_files
}

# ── OpenVPN scaffolding ────────────────────────────────────────────────
ensure_openvpn_dirs() {
    mkdir -p "$OPENVPN_ROOT/server" "$OPENVPN_ROOT/clients" "$OPENVPN_ROOT/ccd" "$OPENVPN_ROOT/limits"
    # Some distros (Arch) lack the "nogroup" group that the generated
    # server.conf references — create it so OpenVPN can start.
    getent group nogroup >/dev/null 2>&1 || groupadd -r nogroup 2>/dev/null || true
    # The tun device is required; try to load the kernel module if missing.
    if [[ ! -e /dev/net/tun ]]; then
        mkdir -p /dev/net
        modprobe tun 2>/dev/null || true
        mknod /dev/net/tun c 10 200 2>/dev/null || true
        chmod 600 /dev/net/tun 2>/dev/null || true
    fi
    if [[ -e /dev/net/tun ]]; then
        step "OpenVPN directories ready ($OPENVPN_ROOT), /dev/net/tun present"
    else
        warn "/dev/net/tun is missing — OpenVPN cannot start (Docker: mount it, bare-metal: modprobe tun)"
    fi
}

start_openvpn_service() {
    # The agent generates server.conf + PKI on first boot; enable/start the
    # systemd instance that reads it.
    if has_systemd; then
        systemctl enable openvpn-server@server >/dev/null 2>&1 || true
        systemctl restart openvpn-server@server >/dev/null 2>&1 && \
            step "OpenVPN server service started" || \
            warn "Could not start openvpn-server@server — check: journalctl -u openvpn-server@server -n 50"
    elif command -v rc-service >/dev/null 2>&1; then
        rc-update add openvpn default >/dev/null 2>&1 || true
        rc-service openvpn start >/dev/null 2>&1 && step "OpenVPN started (OpenRC)" || warn "Start OpenVPN manually"
    else
        warn "No init system detected — start OpenVPN manually: openvpn --config $OPENVPN_ROOT/server/server.conf"
    fi
}

# ── Firewall ───────────────────────────────────────────────────────────
open_firewall_ports() {
    if command -v ufw >/dev/null 2>&1 && ufw status 2>/dev/null | grep -q "Status: active"; then
        ufw allow "$PORT/tcp" >/dev/null 2>&1 && step "UFW: allowed port $PORT/tcp"
        ufw allow "$VPN_PORT/udp" >/dev/null 2>&1 && step "UFW: allowed port $VPN_PORT/udp"
    elif command -v firewall-cmd >/dev/null 2>&1 && firewall-cmd --state >/dev/null 2>&1; then
        firewall-cmd --permanent --add-port="$PORT/tcp" >/dev/null 2>&1
        firewall-cmd --permanent --add-port="$VPN_PORT/udp" >/dev/null 2>&1
        firewall-cmd --reload >/dev/null 2>&1 && step "firewalld: allowed $PORT/tcp + $VPN_PORT/udp"
    fi
}

# ── Systemd unit ───────────────────────────────────────────────────────
write_systemd_unit() {
    cat > "/etc/systemd/system/$SYSTEMD_SERVICE" << UNIT
[Unit]
Description=OVNode OpenVPN Node Agent (${NODE_NAME})
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
User=root
WorkingDirectory=${APP_DIR}
Environment="PATH=${APP_DIR}/.venv/bin:/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"
EnvironmentFile=${APP_DIR}/.env
ExecStart=${UV_BIN} run main.py
Restart=on-failure
RestartSec=3
LimitNOFILE=65536

[Install]
WantedBy=multi-user.target
UNIT
    systemctl daemon-reload >/dev/null 2>&1
    systemctl enable "$SYSTEMD_SERVICE" >/dev/null 2>&1
    step "systemd unit written: /etc/systemd/system/$SYSTEMD_SERVICE"
}

wait_health() {
    local url="$1" tries="${2:-30}"
    local i
    for i in $(seq 1 "$tries"); do
        curl -fsS -o /dev/null --max-time 3 "$url" 2>/dev/null && return 0
        sleep 1
    done
    return 1
}

# ── Install ────────────────────────────────────────────────────────────
fetch_source() {
    if command -v git >/dev/null 2>&1; then
        git clone --depth 1 --branch "$BRANCH" "https://github.com/${REPO}.git" "$APP_DIR" >/dev/null 2>&1 &
        spinner "Cloning repository" $!
    else
        curl -sSLo /tmp/ovn.tar.gz "https://github.com/${REPO}/archive/refs/heads/${BRANCH}.tar.gz" &
        spinner "Downloading source tarball" $!
        mkdir -p "$APP_DIR"
        tar -xzf /tmp/ovn.tar.gz --strip-components=1 -C "$APP_DIR" >/dev/null 2>&1 || die "Extract failed"
        rm -f /tmp/ovn.tar.gz
    fi
}

write_env() {
    # Note: TUNNEL_ADDRESS is intentionally NOT written here — the node's
    # pydantic Settings rejects extra env fields, and the panel pushes the
    # tunnel address via /sync/config when the node is added/updated.
    cat > "$APP_DIR/.env" << EOF
NODE_NAME=${NODE_NAME}
DATA_DIR=${DATA_BASE}/${NODE_NAME}
SERVICE_PORT=${PORT}
API_KEY=${API_KEY}
OPENVPN_PORT=${VPN_PORT}
TLS_METHOD=${TLS_METHOD}
$( if [[ "$IPV6" -eq 1 ]]; then echo "OVNODE_ENABLE_IPV6=1"; fi )
$( if [[ -n "$TLS_KEY" ]]; then echo "SSL_KEYFILE=${TLS_KEY}"; fi )
$( if [[ -n "$TLS_CERT" ]]; then echo "SSL_CERTFILE=${TLS_CERT}"; fi )
EOF
    chmod 600 "$APP_DIR/.env"
    step ".env written"
}

do_install() {
    if [[ -d "$APP_DIR" ]]; then die "Already installed ($APP_DIR exists). Use 'uninstall' first."; fi
    mkdir -p "$DATA_BASE/$NODE_NAME"

    sep; info "Downloading OVNode ($BRANCH)..."
    fetch_source

    info "Installing Python dependencies (uv sync)..."
    cd "$APP_DIR"
    "$UV_BIN" sync --quiet 2>&1 &
    spinner "Python packages installed" $!

    setup_tls
    write_env

    local scheme="http"
    if [[ "$TLS_METHOD" != "none" ]]; then scheme="https"; fi
    local host; host="$(hostname -I 2>/dev/null | awk '{print $1}')"

    if [[ "$DOCKER" -eq 1 ]]; then
        setup_docker
    else
        if ! has_systemd; then
            warn "systemd not found — start the agent manually: cd $APP_DIR && $UV_BIN run main.py"
        else
            write_systemd_unit
            systemctl restart "$SYSTEMD_SERVICE" >/dev/null 2>&1 &
            spinner "Node agent service started" $!
        fi
    fi

    # First boot generates the PKI + server.conf; wait for the agent to
    # answer /sync/health before bringing up OpenVPN so the config exists.
    if ! wait_health "${scheme}://127.0.0.1:${PORT}/sync/health" 45; then
        warn "Agent did not answer /sync/health — check: journalctl -u $SYSTEMD_SERVICE -n 50"
    fi

    ensure_openvpn_dirs
    # In Docker the OpenVPN server runs inside the container — only manage
    # it on the host for native installs.
    if [[ "$DOCKER" -eq 0 ]]; then start_openvpn_service; fi
    setup_nat
    open_firewall_ports

    sep; line ""
    step "${B}Installation complete!${NC}"
    line ""
    field "Node name"   "$NODE_NAME"
    field "Service"     "${WH}${scheme}://${host}:${PORT}${NC}"
    field "OpenVPN"     "${VPN_PORT}/udp"
    field "API key"     "${GR}${API_KEY}${NC}"
    field "Data"        "$DATA_BASE/$NODE_NAME"
    field "OpenVPN cfg" "$OPENVPN_ROOT/server"
    line ""
    info "Add this node to your panel:"
    info "  Panel → Nodes → Add Node → address ${host}, port ${PORT},"
    info "  API key ${API_KEY} → save."
    line ""
}

# ── Docker ─────────────────────────────────────────────────────────────
setup_docker() {
    if ! command -v docker >/dev/null 2>&1; then
        info "Installing Docker Engine..."
        if [[ "$PKG_INSTALL" == apt* ]]; then
            $PKG_UPDATE >/dev/null 2>&1 || true
            $PKG_INSTALL docker.io >/dev/null 2>&1 \
                || $PKG_INSTALL docker-ce >/dev/null 2>&1 \
                || die "Could not install Docker via apt. Install manually: https://docs.docker.com/engine/install/"
        else
            pkg_install docker docker-compose-plugin >/dev/null 2>&1 || pkg_install docker
        fi
        command -v docker >/dev/null 2>&1 || die "Docker binary not found"
    fi
    command -v docker compose >/dev/null 2>&1 || command -v docker-compose >/dev/null 2>&1 \
        || die "Docker Compose v2 is required (docker compose plugin)"

    local compose="$DATA_BASE/$NODE_NAME/docker-compose.yml"
    mkdir -p "$DATA_BASE/$NODE_NAME"
    cat > "$compose" << COMPOSE
services:
  ovnode:
    build:
      context: ${APP_DIR}
      dockerfile: Dockerfile
    container_name: ovnode-${NODE_NAME}
    restart: unless-stopped
    network_mode: host
    environment:
      SERVICE_PORT: ${PORT}
      API_KEY: ${API_KEY}
      OPENVPN_PORT: ${VPN_PORT}
      TLS_METHOD: ${TLS_METHOD}
      OVNODE_OPENVPN_ROOT: /etc/openvpn
$( if [[ "$IPV6" -eq 1 ]]; then echo "      OVNODE_ENABLE_IPV6: 1"; fi )
$( [[ -n "$TLS_KEY" ]] && echo "      SSL_KEYFILE: ${TLS_KEY}" )
$( [[ -n "$TLS_CERT" ]] && echo "      SSL_CERTFILE: ${TLS_CERT}" )
    volumes:
      - ${OPENVPN_ROOT}:/etc/openvpn
      - ${DATA_BASE}/${NODE_NAME}:/app/data
      - /dev/net/tun:/dev/net/tun
    cap_add:
      - NET_ADMIN
      - SYS_MODULE
    logging:
      options:
        max-size: "1m"
        max-file: "3"
COMPOSE

    info "Building and starting Docker container (first build takes a while)..."
    ( cd "$APP_DIR" && docker compose -f "$compose" up -d --build ) >/dev/null 2>&1 &
    spinner "Docker container started" $!
}

# ── Update ─────────────────────────────────────────────────────────────
do_update() {
    [[ -d "$APP_DIR" ]] || die "Not installed ($APP_DIR missing)"
    # Recover the node name from the installed .env when not passed on the CLI
    [[ -n "$NODE_NAME" ]] || NODE_NAME="$(grep -E '^NODE_NAME=' "$APP_DIR/.env" 2>/dev/null | head -1 | cut -d= -f2- | tr -d '"' || true)"
    : "${NODE_NAME:=node-1}"
    line ""; info "Updating OVNode..."
    # Auto-detect the deployment mode: a compose file means this install was
    # done with --docker, even when `update` is called without the flag.
    if [[ -f "$DATA_BASE/$NODE_NAME/docker-compose.yml" ]]; then
        DOCKER=1
        info "Detected Docker deployment (compose file present)"
    fi
    ensure_uv
    backup_dir "$DATA_BASE" "node"
    backup_dir "$OPENVPN_ROOT/server/pki" "node-pki"

    cd "$APP_DIR"
    if [[ -d .git ]]; then
        git stash --quiet 2>/dev/null || true
        git pull --rebase origin "$BRANCH" 2>&1 &
        spinner "Pulling latest changes" $!
        git stash pop --quiet 2>/dev/null || true
    else
        warn "No git checkout — re-downloading source over existing install (.env preserved)"
        curl -sSLo /tmp/ovn.tar.gz "https://github.com/${REPO}/archive/refs/heads/${BRANCH}.tar.gz" &
        spinner "Downloading source" $!
        tar -xzf /tmp/ovn.tar.gz --strip-components=1 -C "$APP_DIR" >/dev/null 2>&1 || die "Extract failed"
        rm -f /tmp/ovn.tar.gz
    fi

    "$UV_BIN" sync --quiet 2>&1 &
    spinner "Updating Python dependencies" $!

    local scheme="http"
    if [[ "$TLS_METHOD" != "none" ]]; then scheme="https"; fi
    if [[ "$DOCKER" -eq 1 ]]; then
        ( cd "$APP_DIR" && docker compose -f "$DATA_BASE/$NODE_NAME/docker-compose.yml" up -d --build ) >/dev/null 2>&1 &
        spinner "Recreating Docker container" $!
    else
        systemctl restart "$SYSTEMD_SERVICE" >/dev/null 2>&1 &
        spinner "Node agent restarted" $!
    fi
    setup_nat
    wait_health "${scheme}://127.0.0.1:${PORT}/sync/health" 30 \
        || warn "Agent did not answer /sync/health after update — check: journalctl -u $SYSTEMD_SERVICE -n 50"
    step "Update complete"
    line ""
}

# ── Uninstall ──────────────────────────────────────────────────────────
do_uninstall() {
    [[ -d "$APP_DIR" ]] || die "Not installed ($APP_DIR missing)"
    [[ -n "$NODE_NAME" ]] || NODE_NAME="$(grep -E '^NODE_NAME=' "$APP_DIR/.env" 2>/dev/null | head -1 | cut -d= -f2- | tr -d '"' || true)"
    : "${NODE_NAME:=node-1}"
    confirm "Remove OVNode and stop all services?" || die "Cancelled."

    systemctl stop "$SYSTEMD_SERVICE" "$NAT_SERVICE" openvpn-server@server 2>/dev/null || true
    systemctl disable "$SYSTEMD_SERVICE" "$NAT_SERVICE" openvpn-server@server 2>/dev/null || true
    rm -f "/etc/systemd/system/$SYSTEMD_SERVICE" "/etc/systemd/system/$NAT_SERVICE"
    systemctl daemon-reload 2>/dev/null || true

    if command -v docker >/dev/null 2>&1 && [[ -f "$DATA_BASE/$NODE_NAME/docker-compose.yml" ]]; then
        ( cd "$APP_DIR" && docker compose -f "$DATA_BASE/$NODE_NAME/docker-compose.yml" down ) >/dev/null 2>&1 || true
        docker rm -f "ovnode-$NODE_NAME" >/dev/null 2>&1 || true
    fi

    rm -f /usr/local/sbin/ovnode-nat.sh /etc/sysctl.d/99-ovnode.conf
    rm -rf "$APP_DIR"
    if [[ "$PURGE" -eq 1 ]]; then
        backup_dir "$DATA_BASE" "node-pre-purge"
        rm -rf "$DATA_BASE"
        backup_dir "$OPENVPN_ROOT" "openvpn-pre-purge"
        rm -rf "$OPENVPN_ROOT"
        step "Data and OpenVPN configuration removed"
    else
        step "App removed. Data kept at $DATA_BASE and $OPENVPN_ROOT (use --purge to remove them too)"
    fi
    step "OVNode uninstalled"
    line ""
}

# ── Interactive setup ──────────────────────────────────────────────────
interactive_setup() {
    local api_default
    api_default="$(openssl rand -hex 32)"
    NODE_NAME="$(ask "Node name" "node-1")"
    PORT="$(ask "Service port" "$(find_free_port "$DEFAULT_PORT")")"
    VPN_PORT="$(ask "OpenVPN port" "$DEFAULT_VPN")"
    API_KEY="$(ask "API key (blank=generate)" "$api_default")"

    sep; line "  TLS:"
    line "  ${WH}1${NC})  Let's Encrypt (domain)      ${WH}2${NC})  Let's Encrypt (IP)"
    line "  ${WH}3${NC})  Self-signed                 ${WH}4${NC})  Custom cert path"
    line "  ${WH}5${NC})  None (HTTP)"
    local tls_choice
    tls_choice="$(ask "TLS mode" "5")"
    case "${tls_choice:-5}" in
        1) TLS_METHOD="letsencrypt"; TLS_DOMAIN="$(ask "Domain" "")"; [[ -n "$TLS_DOMAIN" ]] || die "Domain required for Let's Encrypt" ;;
        2) TLS_METHOD="letsencrypt-ip"; TLS_DOMAIN="$(hostname -I 2>/dev/null | awk '{print $1}')" ;;
        3) TLS_METHOD="selfsigned" ;;
        4) TLS_METHOD="custom"; TLS_KEY="$(ask "Key file" "")"; TLS_CERT="$(ask "Cert file" "")" ;;
        *) TLS_METHOD="none" ;;
    esac
}

# ── Main ───────────────────────────────────────────────────────────────
main() {
    parse_args "$@"
    command clear >/dev/null 2>&1 || true
    line ""
    line "  ${B}OVNode${NC} — OpenVPN Node Agent Installer ${GY}v${VERSION}${NC}"
    sep; line ""

    case "$ACTION" in
        uninstall) do_uninstall; exit 0 ;;
        update)    [[ "$YES" -eq 1 ]] || confirm "Update OVNode now?" || exit 0; do_update; exit 0 ;;
    esac

    if [[ -d "$APP_DIR" ]]; then
        warn "OVNode is already installed"
        if is_tty; then
            line ""
            line "  ${GR}1${NC})  Update to latest version"
            line "  ${YL}2${NC})  Uninstall"
            line "  ${GY}3${NC})  Quit"
            line ""
            local choice; choice="$(ask "Select" "1")"
            case "${choice:-1}" in
                1) do_update ;;
                2) do_uninstall ;;
                *) exit 0 ;;
            esac
        else
            info "Already installed — run with 'update' to refresh it."
        fi
        exit 0
    fi

    detect_os
    if [[ "$YES" -eq 0 && ( -z "$PORT" || -z "$API_KEY" ) ]]; then
        interactive_setup
    else
        : "${PORT:=$(find_free_port "$DEFAULT_PORT")}"
        : "${VPN_PORT:=$DEFAULT_VPN}"
        : "${NODE_NAME:=node-1}"
        : "${TLS_METHOD:=none}"
        [[ -n "$API_KEY" ]] || API_KEY="$(openssl rand -hex 32)"
    fi
    validate_input

    field "OS"        "$OS_NAME"
    field "Mode"      "$([ $DOCKER -eq 1 ] && echo Docker || echo Native)"
    field "Node"      "$NODE_NAME"
    field "Service"   "$PORT"
    field "OpenVPN"   "$VPN_PORT/udp"
    field "TLS"       "$TLS_METHOD"
    field "Install"   "$APP_DIR"
    field "Data"      "$DATA_BASE/$NODE_NAME"
    if [[ "$TLS_METHOD" == "none" ]]; then
        warn "TLS is DISABLED — the API key is a bearer secret sent in plaintext."
        warn "For internet exposure use --tls letsencrypt/selfsigned; for LAN-only use a private network."
    fi
    sep
    confirm "Proceed with installation?" || die "Cancelled."

    check_root
    check_deps
    ensure_uv
    do_install
}

check_root() { if [[ "$EUID" -ne 0 ]]; then die "Must run as root."; fi; }

check_deps() {
    local missing=()
    for cmd in curl tar openssl git python3; do
        command -v "$cmd" >/dev/null 2>&1 || missing+=("$cmd")
    done
    [[ ${#missing[@]} -eq 0 ]] || pkg_install "${missing[@]}"
    if ! command -v openvpn >/dev/null 2>&1; then
        info "Installing OpenVPN + easy-rsa (for client PKI)..."
        pkg_install openvpn easy-rsa
    fi
    step "System dependencies present"
}

main "$@"
